package org.springframework.samples.petclinic.acceptance;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

/** A supplied weekend registration date is rolled forward to Monday, and derived values use it. */
class RegistrationBusinessDayTest extends AcceptanceBase {

	@Test
	void suppliedSaturdayRollsToMonday() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2026-10-17");
		assertEquals("2026-10-19", fetchOwner(createOwnerOk(o)).get("registrationDate").asText());
	}

	@Test
	void suppliedWeekdayIsKept() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2026-10-14");
		assertEquals("2026-10-14", fetchOwner(createOwnerOk(o)).get("registrationDate").asText());
	}

	@Test
	void membershipYearUsesAdjustedDate() throws Exception {
		// Sunday 2034-12-31 rolls to Monday 2035-01-01
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2034-12-31");
		JsonNode owner = fetchOwner(createOwnerOk(o));
		assertEquals("2035-01-01", owner.get("registrationDate").asText());
		assertEquals(owner.get("customerCode").asText() + "-M35", owner.get("membershipNumber").asText());
	}

	@Test
	void dailyLimitCountsPerAdjustedBusinessDay() throws Exception {
		// Saturday and Sunday both roll to Monday 2030-01-07 and share its quota
		for (int i = 0; i < 100; i++) {
			ObjectNode o = ownerNode();
			o.put("registrationDate", i % 2 == 0 ? "2030-01-05" : "2030-01-06");
			createOwnerOk(o);
		}
		ObjectNode monday = ownerNode();
		monday.put("registrationDate", "2030-01-07");
		createOwner(monday).andExpect(status().is4xxClientError());
		ObjectNode friday = ownerNode();
		friday.put("registrationDate", "2030-01-04");
		createOwnerOk(friday);
	}
}
